import { useQuery } from "@tanstack/react-query";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import { DatePicker } from "@/components/ui/date-picker";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";

import { QuestionLabel } from "@/components/Questionnaire/QuestionLabel";

import query from "@/Utils/request/query";
import { cn } from "@/lib/utils";
import {
  ENCOUNTER_ADMIT_SOURCE,
  ENCOUNTER_DIET_PREFERENCE,
  ENCOUNTER_DISCHARGE_DISPOSITION,
  ENCOUNTER_PRIORITY,
  EncounterStatus,
  type EncounterAdmitSources,
  type EncounterClass,
  type EncounterDietPreference,
  type EncounterDischargeDisposition,
  type EncounterEdit,
  type EncounterPriority,
  type EncounterRead,
} from "@/types/emr/encounter/encounter";
import encounterApi from "@/types/emr/encounter/encounterApi";
import { QuestionValidationError } from "@/types/questionnaire/batch";
import type {
  QuestionnaireResponse,
  ResponseValue,
} from "@/types/questionnaire/form";
import type { Question } from "@/types/questionnaire/question";
import {
  FieldDefinitions,
  useFieldError,
  validateFields,
} from "@/types/questionnaire/validation";
import careConfig from "@careConfig";
import { useQueryParams } from "raviger";

interface EncounterQuestionProps {
  question: Question;
  encounterId: string;
  questionnaireResponse: QuestionnaireResponse;
  updateQuestionnaireResponseCB: (
    values: ResponseValue[],
    questionId: string,
    note?: string,
  ) => void;
  disabled?: boolean;
  clearError: () => void;
  organizations?: string[];
  patientId?: string;
  facilityId: string;
  errors?: QuestionValidationError[];
}

const NON_SELECTABLE_ENCOUNTER_STATUSES: EncounterStatus[] = [
  EncounterStatus.DISCHARGED,
  EncounterStatus.UNKNOWN,
  EncounterStatus.COMPLETED,
];

const ENCOUNTER_FIELDS: FieldDefinitions = {
  DISCHARGE_DISPOSITION: {
    key: "hospitalization.discharge_disposition",
    required: true,
  },
} as const;

export function validateEncounterQuestion(
  value: EncounterEdit | undefined,
  questionId: string,
): QuestionValidationError[] {
  const errors: QuestionValidationError[] = [];

  if (
    value?.status === EncounterStatus.DISCHARGED &&
    ["imp", "obsenc", "emer"].includes(value.encounter_class) &&
    !value?.hospitalization?.discharge_disposition
  ) {
    errors.push(...validateFields(value, questionId, ENCOUNTER_FIELDS));
  }

  return errors;
}

export function EncounterQuestion({
  question,
  questionnaireResponse,
  updateQuestionnaireResponseCB,
  disabled,
  clearError,
  encounterId,
  facilityId,
  errors = [],
}: EncounterQuestionProps) {
  // Fetch encounter data
  const { data: encounterData, isLoading } = useQuery({
    queryKey: ["encounter", encounterId],
    queryFn: query(encounterApi.get, {
      pathParams: { id: encounterId },
      queryParams: { facility: facilityId },
    }),
    enabled: !!encounterId,
  });
  const { t } = useTranslation();
  const [{ toDischarge }] = useQueryParams();
  const { hasError, getError } = useFieldError(
    questionnaireResponse.question_id,
    errors,
  );

  const [encounter, setEncounter] = useState<EncounterEdit>({
    status: EncounterStatus.UNKNOWN,
    encounter_class: careConfig.defaultEncounterType,
    period: {
      start: new Date().toISOString(),
      end: undefined,
    },
    priority: "routine",
    external_identifier: "",
    hospitalization: {
      re_admission: false,
      admit_source: "other",
      discharge_disposition: careConfig.defaultDischargeDisposition,
      diet_preference: "none",
    },
    discharge_summary_advice: null,
  });

  useEffect(() => {
    const isStartDateInFuture =
      !!encounter.period.start && new Date(encounter.period.start) > new Date();

    if (
      encounter.status === EncounterStatus.DISCHARGED ||
      encounter.status === EncounterStatus.DISCONTINUED ||
      encounter.status === EncounterStatus.COMPLETED
    ) {
      // Always set end date — if start is in the future, BE will reject it
      if (!encounter.period.end) {
        handleUpdateEncounter({
          period: {
            ...encounter.period,
            end: new Date().toISOString(),
          },
        });
      }
    } else if (
      encounter.status === EncounterStatus.CANCELLED ||
      encounter.status === EncounterStatus.ENTERED_IN_ERROR
    ) {
      if (isStartDateInFuture) {
        // Valid transition from future encounters — don't set end date
        if (encounter.period.end) {
          handleUpdateEncounter({
            period: {
              ...encounter.period,
              end: undefined,
            },
          });
        }
      } else if (!encounter.period.end) {
        handleUpdateEncounter({
          period: {
            ...encounter.period,
            end: new Date().toISOString(),
          },
        });
      }
    } else {
      if (encounter.period.end) {
        handleUpdateEncounter({
          period: {
            ...encounter.period,
            end: undefined,
          },
        });
      }
    }
    // Re-run when the period changes too (e.g. status picked first, then the
    // start date edited to a future date) so the end date stays consistent.
  }, [encounter.status, encounter.period.start, encounter.period.end]);

  // Transform EncounterRead to EncounterEdit format
  const transformEncounterForUpdate = (
    read: EncounterRead,
  ): Partial<EncounterEdit> => {
    return {
      status: read.status,
      encounter_class: read.encounter_class,
      period: read.period,
      priority: read.priority,
      hospitalization: read.hospitalization,
      external_identifier: read.external_identifier,
      discharge_summary_advice: read.discharge_summary_advice,
    };
  };

  // Update encounter state when data is loaded
  useEffect(() => {
    if (encounterData) {
      const updates = transformEncounterForUpdate(encounterData);
      if (toDischarge === "true") {
        updates.status = EncounterStatus.DISCHARGED;
      }
      handleUpdateEncounter(updates);
    }
  }, [encounterData]);

  useEffect(() => {
    const formStateValue = (
      questionnaireResponse.values[0]?.value as EncounterEdit[]
    )?.[0];
    if (formStateValue) {
      setEncounter(() => ({
        ...formStateValue,
      }));
    }
  }, [questionnaireResponse]);

  const handleUpdateEncounter = (updates: Partial<EncounterEdit>) => {
    clearError();
    const newEncounter = { ...encounter, ...updates };
    if (["amb", "vr", "hh"].includes(newEncounter.encounter_class)) {
      newEncounter.hospitalization = {};
    }

    if (
      ["imp", "obsenc", "emer"].includes(encounter.encounter_class) &&
      newEncounter.status === EncounterStatus.DISCHARGED
    ) {
      newEncounter.hospitalization = {
        ...newEncounter.hospitalization,
        discharge_disposition:
          newEncounter.hospitalization?.discharge_disposition ??
          careConfig.defaultDischargeDisposition,
      };
    } else if ("hospitalization" in newEncounter) {
      newEncounter.hospitalization = {
        ...newEncounter.hospitalization,
        discharge_disposition:
          encounterData?.hospitalization?.discharge_disposition,
      };
    }

    // Create the full encounter request object
    const encounterRequest: EncounterEdit = {
      ...newEncounter,
    };

    // Create the response value with the encounter request
    const responseValue: ResponseValue = {
      type: "encounter",
      value: [encounterRequest],
    };

    updateQuestionnaireResponseCB(
      [responseValue],
      questionnaireResponse.question_id,
    );
  };

  if (isLoading) {
    return <div>{t("loading_encounter")}</div>;
  }

  const isCurrentStatusNonSelectable =
    NON_SELECTABLE_ENCOUNTER_STATUSES.includes(encounter.status);
  const selectableEncounterStatuses = Object.values(EncounterStatus).filter(
    (encounterStatus) => {
      if (isCurrentStatusNonSelectable) {
        return encounterStatus === encounter.status;
      }
      return !NON_SELECTABLE_ENCOUNTER_STATUSES.includes(encounterStatus);
    },
  );

  return (
    <div className="space-y-6">
      <QuestionLabel question={question} />
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Basic Details */}
        <div className="space-y-2">
          <Label>{t("encounter_status")}</Label>
          <Select
            value={encounter.status}
            onValueChange={(value: EncounterStatus) =>
              handleUpdateEncounter({
                status: value,
              })
            }
            disabled={
              disabled || encounter.status === EncounterStatus.DISCHARGED
            }
          >
            <SelectTrigger>
              <SelectValue placeholder={t("select_status")} />
              <SelectValue placeholder={t("select_status")} />
            </SelectTrigger>
            <SelectContent>
              {selectableEncounterStatuses.map(
                (encounterStatus: EncounterStatus) => (
                  <SelectItem key={encounterStatus} value={encounterStatus}>
                    {t(`encounter_status__${encounterStatus}`)}
                  </SelectItem>
                ),
              )}
            </SelectContent>
          </Select>
        </div>

        <div className="space-y-2">
          <Label>{t("encounter_class")}</Label>
          <Select
            value={encounter.encounter_class}
            onValueChange={(value: EncounterClass) =>
              handleUpdateEncounter({
                encounter_class: value,
              })
            }
            disabled={disabled}
          >
            <SelectTrigger>
              <SelectValue placeholder={t("select_class")} />
            </SelectTrigger>
            <SelectContent>
              {careConfig.encounterClasses.map((encounterClass) => (
                <SelectItem key={encounterClass} value={encounterClass}>
                  {t(`encounter_class__${encounterClass}`)}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <div className="space-y-2">
          <Label>{t("priority")}</Label>
          <Select
            value={encounter.priority}
            onValueChange={(value: EncounterPriority) =>
              handleUpdateEncounter({
                priority: value,
              })
            }
            disabled={disabled}
          >
            <SelectTrigger>
              <SelectValue placeholder={t("select_priority")} />
            </SelectTrigger>
            <SelectContent>
              {ENCOUNTER_PRIORITY.map((priority) => (
                <SelectItem key={priority} value={priority}>
                  {t(`encounter_priority__${priority}`)}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <div className="space-y-2">
          <Label>{t("hospital_identifier")}</Label>
          <Input
            value={encounter.external_identifier || ""}
            onChange={(e) =>
              handleUpdateEncounter({ external_identifier: e.target.value })
            }
            disabled={disabled}
            placeholder={t("ip_op_obs_emr_number")}
          />
        </div>
      </div>

      {/* Mark for discharge button - Show if not already discharged */}
      {encounter.status !== EncounterStatus.DISCHARGED && (
        <div className="col-span-2 border border-gray-200 rounded-lg p-2 bg-gray-50">
          <div className="flex flex-col sm:flex-row sm:items-center gap-4 sm:justify-between">
            <div className="space-y-1">
              <h3 className="text-sm font-medium">{t("discharge_patient")}</h3>
            </div>
            <Button
              variant="outline"
              size="sm"
              disabled={disabled}
              onClick={() =>
                handleUpdateEncounter({ status: EncounterStatus.DISCHARGED })
              }
            >
              {t("mark_for_discharge")}
            </Button>
          </div>
        </div>
      )}

      {(encounter.status === EncounterStatus.DISCHARGED ||
        encounter.discharge_summary_advice) && (
        <div className="space-y-6">
          <div className="space-y-2">
            <Label>{t("discharge_summary_advice")}</Label>
            <Textarea
              defaultValue={encounter.discharge_summary_advice || ""}
              onChange={(e) => {
                handleUpdateEncounter({
                  discharge_summary_advice: e.target.value || null,
                });
              }}
              disabled={disabled}
              placeholder={t("enter_discharge_summary_advice")}
            />
          </div>
        </div>
      )}

      {/* Hospitalization Details - Only show for relevant encounter classes */}
      {["imp", "obsenc", "emer"].includes(encounter.encounter_class) && (
        <div className="col-span-2 border border-gray-200 rounded-lg p-4 space-y-4">
          <h3 className="text-lg font-semibold break-words">
            {t("hospitalization_details")}
          </h3>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="flex items-center space-x-2 overflow-x-auto">
              <Switch
                checked={encounter.hospitalization?.re_admission || false}
                onCheckedChange={(checked: boolean) => {
                  if (!encounter.hospitalization) return;
                  handleUpdateEncounter({
                    hospitalization: {
                      ...encounter.hospitalization,
                      re_admission: checked,
                    },
                  });
                }}
                disabled={disabled}
              />
              <Label>{t("readmission")}</Label>
            </div>

            <div className="space-y-2">
              <Label>{t("admit_source")}</Label>
              <Select
                value={encounter.hospitalization?.admit_source}
                onValueChange={(value: EncounterAdmitSources) => {
                  if (!encounter.hospitalization) return;
                  handleUpdateEncounter({
                    hospitalization: {
                      ...encounter.hospitalization,
                      admit_source: value,
                    },
                  });
                }}
                disabled={disabled}
              >
                <SelectTrigger>
                  <SelectValue placeholder={t("select_admit_source")} />
                </SelectTrigger>
                <SelectContent>
                  {ENCOUNTER_ADMIT_SOURCE.map((admitSource) => (
                    <SelectItem key={admitSource} value={admitSource}>
                      {t(`encounter_admit_sources__${admitSource}`)}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Show discharge disposition and date when status is discharged OR has discharge disposition */}
            {(encounter.status === EncounterStatus.DISCHARGED ||
              encounter.hospitalization?.discharge_disposition) && (
              <>
                <div className="space-y-2">
                  <Label>
                    {t("discharge_disposition")}
                    <span className="text-red-500">*</span>
                  </Label>
                  <Select
                    value={
                      encounter.hospitalization?.discharge_disposition ??
                      careConfig.defaultDischargeDisposition
                    }
                    onValueChange={(value: EncounterDischargeDisposition) => {
                      if (!encounter.hospitalization) return;
                      handleUpdateEncounter({
                        hospitalization: {
                          ...encounter.hospitalization,
                          discharge_disposition: value,
                        },
                      });
                    }}
                    disabled={disabled}
                  >
                    <SelectTrigger
                      className={cn(
                        hasError(ENCOUNTER_FIELDS.DISCHARGE_DISPOSITION.key) &&
                          "ring-1 ring-red-500",
                      )}
                    >
                      <SelectValue
                        placeholder={t("select_discharge_disposition")}
                      />
                    </SelectTrigger>
                    <SelectContent>
                      {ENCOUNTER_DISCHARGE_DISPOSITION.map((disposition) => (
                        <SelectItem key={disposition} value={disposition}>
                          {t(`encounter_discharge_disposition__${disposition}`)}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  {hasError(ENCOUNTER_FIELDS.DISCHARGE_DISPOSITION.key) && (
                    <p className="text-red-500 text-sm">
                      {
                        getError(ENCOUNTER_FIELDS.DISCHARGE_DISPOSITION.key)
                          ?.msg
                      }
                    </p>
                  )}
                </div>

                {encounter.status === EncounterStatus.DISCHARGED && (
                  <div className="space-y-2">
                    <Label>{t("discharge_date_time")}</Label>
                    <div className="flex gap-1 flex-wrap">
                      <DatePicker
                        date={
                          encounter.period.end
                            ? new Date(encounter.period.end)
                            : new Date()
                        }
                        onChange={(newDate) => {
                          if (!newDate) return;
                          const currentDate = encounter.period.end
                            ? new Date(encounter.period.end)
                            : new Date();
                          const updatedDate = new Date(newDate);
                          updatedDate.setHours(currentDate.getHours());
                          updatedDate.setMinutes(currentDate.getMinutes());
                          handleUpdateEncounter({
                            period: {
                              ...encounter.period,
                              end: updatedDate.toISOString(),
                            },
                          });
                        }}
                        disabled={(date) => {
                          if (!encounter.period.start) return false;
                          const startDate = new Date(encounter.period.start);
                          startDate.setHours(0, 0, 0, 0);
                          return date < startDate;
                        }}
                        dateFormat="d/M/yyyy"
                        className="flex-1"
                      />
                      <Input
                        type="time"
                        className="flex-1 border-t-0 sm:border-t text-sm border-gray-200 h-9"
                        value={
                          encounter.period.end
                            ? new Date(encounter.period.end).toLocaleTimeString(
                                [],
                                {
                                  hour: "2-digit",
                                  minute: "2-digit",
                                  hour12: false,
                                },
                              )
                            : new Date().toLocaleTimeString([], {
                                hour: "2-digit",
                                minute: "2-digit",
                                hour12: false,
                              })
                        }
                        onChange={(e) => {
                          const [hours, minutes] = e.target.value
                            .split(":")
                            .map(Number);
                          if (isNaN(hours) || isNaN(minutes)) return;
                          const updatedDate = new Date(
                            encounter.period.end || new Date(),
                          );
                          updatedDate.setHours(hours);
                          updatedDate.setMinutes(minutes);
                          handleUpdateEncounter({
                            period: {
                              ...encounter.period,
                              end: updatedDate.toISOString(),
                            },
                          });
                        }}
                        disabled={disabled}
                      />
                    </div>
                  </div>
                )}
              </>
            )}

            <div className="space-y-2">
              <Label>{t("diet_preference")}</Label>
              <Select
                value={encounter.hospitalization?.diet_preference}
                onValueChange={(value: EncounterDietPreference) => {
                  if (!encounter.hospitalization) return;
                  handleUpdateEncounter({
                    hospitalization: {
                      ...encounter.hospitalization,
                      diet_preference: value,
                    },
                  });
                }}
                disabled={disabled}
              >
                <SelectTrigger>
                  <SelectValue placeholder={t("select_diet_preference")} />
                </SelectTrigger>
                <SelectContent>
                  {ENCOUNTER_DIET_PREFERENCE.map((dietPreference) => (
                    <SelectItem key={dietPreference} value={dietPreference}>
                      {t(`encounter_diet_preference__${dietPreference}`)}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
import { expect, test, type Page } from "@playwright/test";
import {
  getEncounterCreateDialog,
  getFutureDateButtonFromCalendar,
  openCalendarAndGetNextMonthButton,
  openCreateEncounterDialog,
  selectRandomEncounterClass,
  selectStatusInCreateDialog,
} from "tests/facility/patient/encounter/encounterFormHelpers";

test.use({ storageState: "tests/.auth/user.json" });

// Assert only the stable portion of the backend validation message; field-path
// prefixes like "period:" may change while the core error stays the same.
const VALIDATION_ERROR_TEXT = "Start Date cannot be greater than End Date";

async function selectFutureDateInCalendar(page: Page) {
  const nextMonthButton = await openCalendarAndGetNextMonthButton(page);
  await expect(nextMonthButton).toBeEnabled();
  await nextMonthButton.click();

  const futureDayButton = getFutureDateButtonFromCalendar(page);
  await expect(futureDayButton).toBeEnabled();
  await futureDayButton.click();
}

async function createPlannedEncounterWithFutureDate(page: Page) {
  await openCreateEncounterDialog(page);
  await selectRandomEncounterClass(page);
  await selectStatusInCreateDialog(page, "Planned");
  await selectFutureDateInCalendar(page);

  const dialog = getEncounterCreateDialog(page);

  // Submit navigates to the encounter detail page. Register the URL listener
  // before clicking so a fast navigation can't race past it.
  await Promise.all([
    page.waitForURL(/\/encounter\/[^/]+/),
    dialog.getByRole("button", { name: /^Create Encounter/ }).click(),
  ]);
  await expect(
    page.getByRole("button", { name: "Encounter Actions" }),
  ).toBeVisible();
}

// Update-encounter form uses a bare <Label> + <SelectTrigger> (no FormLabel/htmlFor),
// so the combobox has no programmatic accessible name. Anchor on the label and walk
// to its immediate parent (the space-y-2 wrapper that contains exactly one combobox).
function encounterStatusCombobox(page: Page) {
  return page
    .locator('label[data-slot="label"]')
    .filter({ hasText: /^Encounter Status$/ })
    .locator("..")
    .getByRole("combobox");
}

async function openEncounterUpdateForm(page: Page) {
  await page.getByRole("tab", { name: "Details" }).click();
  await page.getByRole("link", { name: "Update Encounter" }).click();
  await expect(encounterStatusCombobox(page)).toBeVisible();
}

async function changeStatus(page: Page, status: string) {
  await encounterStatusCombobox(page).click();
  await page.getByRole("option", { name: status, exact: true }).click();
}

async function submitQuestionnaire(page: Page) {
  await page.getByRole("button", { name: "Submit", exact: true }).click();
}

async function expectSubmissionSuccess(page: Page) {
  await expect(
    page.getByText("Questionnaire submitted successfully"),
  ).toBeVisible();
}

async function expectSubmissionBlockedByPeriodError(page: Page) {
  await expect(page.getByText("Failed to submit questionnaire")).toBeVisible();
  await expect(page.getByText(VALIDATION_ERROR_TEXT)).toBeVisible();
}

// Ensures the encounter ends in a terminal state so the patient's 5-live-encounter
// limit isn't reached across repeated runs.
async function cancelEncounterFromCurrentForm(page: Page) {
  await changeStatus(page, "Cancelled");
  await submitQuestionnaire(page);
  await expectSubmissionSuccess(page);
}

test.describe("Planned Encounter Status Transition", () => {
  // Each test creates a live encounter on the shared patient; running in parallel
  // would exceed the backend's live-encounter-per-patient limit and fail creation.
  test.describe.configure({ mode: "serial" });

  test.beforeEach(async ({ page }) => {
    await createPlannedEncounterWithFutureDate(page);
  });

  // Best-effort cleanup: if a test failed before its inline cleanup step, try
  // to cancel the encounter so it doesn't remain live and trip the backend's
  // 5-live-encounter-per-patient limit on later runs.
  test.afterEach(async ({ page }, testInfo) => {
    if (testInfo.status === testInfo.expectedStatus) return;
    try {
      await openEncounterUpdateForm(page);
      await cancelEncounterFromCurrentForm(page);
    } catch {
      // Encounter may already be terminal or the page in an unexpected state.
    }
  });

  test("allows transition from Planned to In Progress", async ({ page }) => {
    await test.step("Open update form", async () => {
      await openEncounterUpdateForm(page);
    });

    await test.step("Transition Planned to In Progress", async () => {
      await changeStatus(page, "In Progress");
      await submitQuestionnaire(page);
      await expectSubmissionSuccess(page);
    });

    await test.step("Cleanup: cancel encounter", async () => {
      await openEncounterUpdateForm(page);
      await cancelEncounterFromCurrentForm(page);
    });
  });

  test("allows transition from Planned to On Hold", async ({ page }) => {
    await test.step("Open update form", async () => {
      await openEncounterUpdateForm(page);
    });

    await test.step("Transition Planned to On Hold", async () => {
      await changeStatus(page, "On Hold");
      await submitQuestionnaire(page);
      await expectSubmissionSuccess(page);
    });

    await test.step("Cleanup: cancel encounter", async () => {
      await openEncounterUpdateForm(page);
      await cancelEncounterFromCurrentForm(page);
    });
  });

  test("allows transition from Planned to Cancelled", async ({ page }) => {
    await test.step("Open update form", async () => {
      await openEncounterUpdateForm(page);
    });

    await test.step("Transition Planned to Cancelled", async () => {
      await cancelEncounterFromCurrentForm(page);
    });
  });

  test("allows transition from Planned to Entered in error", async ({
    page,
  }) => {
    await test.step("Open update form", async () => {
      await openEncounterUpdateForm(page);
    });

    await test.step("Transition Planned to Entered in error", async () => {
      await changeStatus(page, "Entered in error");
      await submitQuestionnaire(page);
      await expectSubmissionSuccess(page);
    });
  });

  test("blocks transition from Planned to Completed with period error", async ({
    page,
  }) => {
    await test.step("Open update form", async () => {
      await openEncounterUpdateForm(page);
    });

    await test.step("Attempt Planned to Completed", async () => {
      await changeStatus(page, "Completed");
      await submitQuestionnaire(page);
      await expectSubmissionBlockedByPeriodError(page);
    });

    await test.step("Cleanup: cancel encounter (still Planned on backend)", async () => {
      // Backend rejected the transition, so the encounter is still Planned.
      // Selecting Cancelled clears the auto-set end date (see EncounterQuestion
      // useEffect handling for future-start Cancelled/EnteredInError), so this
      // submit succeeds and moves the encounter to a terminal state.
      await cancelEncounterFromCurrentForm(page);
    });
  });

  test("blocks transition from Planned to Discontinued with period error", async ({
    page,
  }) => {
    await test.step("Open update form", async () => {
      await openEncounterUpdateForm(page);
    });

    await test.step("Attempt Planned to Discontinued", async () => {
      await changeStatus(page, "Discontinued");
      await submitQuestionnaire(page);
      await expectSubmissionBlockedByPeriodError(page);
    });

    await test.step("Cleanup: cancel encounter (still Planned on backend)", async () => {
      await cancelEncounterFromCurrentForm(page);
    });
  });
});
import { faker } from "@faker-js/faker";
