        invalidateLocalPluginModule();
        server.ws.send({ type: "full-reload" });
      };

      server.watcher.on("add", (filePath) => {
        if (isPluginManifestPath(rootDir, filePath)) {
          reloadLocalPlugins();
        }
      });

